changeSet.sql:
CREATE OR REPLACE FUNCTION check_user_has_email()
RETURNS TRIGGER AS $$
            BEGIN
    IF NOT EXISTS (SELECT 1 FROM email_data WHERE user_id = NEW.id) THEN
        RAISE EXCEPTION 'User % must have at least one email', NEW.id;
            END IF;
            RETURN NEW;
            END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_user_has_phone()
RETURNS TRIGGER AS $$
            BEGIN
    IF NOT EXISTS (SELECT 1 FROM phone_data WHERE user_id = NEW.id) THEN
        RAISE EXCEPTION 'User % must have at least one phone', NEW.id;
            END IF;
            RETURN NEW;
            END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION check_user_has_account()
RETURNS TRIGGER AS $$
            BEGIN
    IF NOT EXISTS (SELECT 1 FROM account WHERE user_id = NEW.id) THEN
        RAISE EXCEPTION 'User % must have only one account', NEW.id;
            END IF;
            RETURN NEW;
            END;
$$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER trg_account_delete_check AFTER DELETE ON account DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_user_has_account();
CREATE CONSTRAINT TRIGGER trg_email_delete_check AFTER DELETE ON email_data DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_user_has_email();
CREATE CONSTRAINT TRIGGER trg_phone_delete_check AFTER DELETE ON phone_data DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_user_has_phone();
